import type { LayoutState, TabGroup, TabGroupLayoutNode, TabPaneLayout } from "../lib/types";
import { normalizeLayout } from "./layout";
import {
  collectLeafIds,
  findFirstLeafId,
  splitLeafWithSubtree,
  type PaneDirection,
  type PaneNode,
} from "./paneTree";

export type TabPaneDropTarget = {
  tabId: string;
  leafId: string;
};

/**
 * Moves a terminal tab's existing pane subtree into a specific leaf of another
 * terminal tab. No terminal session is created or destroyed: ownership moves
 * entirely inside the layout graph so xterm buffers and native PTYs survive.
 */
export function moveTabIntoPaneSplit(
  inputLayout: LayoutState,
  sourceTabId: string,
  targetTabId: string,
  targetLeafId: string,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): LayoutState {
  const state = normalizeLayout(inputLayout);
  if (sourceTabId === targetTabId) return state;

  const sourceTab = state.tabs.find((tab) => tab.id === sourceTabId);
  const targetTab = state.tabs.find((tab) => tab.id === targetTabId);
  const sourceLayout = state.layoutsByTabId[sourceTabId];
  const targetLayout = state.layoutsByTabId[targetTabId];
  if (
    !sourceTab ||
    !targetTab ||
    sourceTab.kind === "browser" ||
    targetTab.kind === "browser" ||
    !sourceLayout ||
    !targetLayout
  ) {
    return state;
  }

  const targetLeafIds = collectLeafIds(targetLayout.root);
  if (!targetLeafIds.includes(targetLeafId)) return state;

  const groups = { ...(state.tabGroups ?? {}) };
  const sourceGroup = findGroupContainingTab(groups, sourceTabId);
  const targetGroup = findGroupContainingTab(groups, targetTabId);
  if (!sourceGroup || !targetGroup) return state;

  // Legacy layouts can give every tab the same leaf id (for example `leaf-init`).
  // Remap only colliding source ids before the subtree is inserted so the combined
  // tree has a one-to-one leaf -> local session mapping.
  const moved = remapPaneLayout(sourceLayout, new Set(targetLeafIds));
  const nextTargetRoot = splitLeafWithSubtree(
    targetLayout.root,
    targetLeafId,
    moved.root,
    direction,
    position,
    ratio,
  );
  if (nextTargetRoot === targetLayout.root) return state;

  let tabGroupLayout = state.tabGroupLayout ?? null;
  const sourceIndex = sourceGroup.tabIds.indexOf(sourceTabId);
  const remainingSourceTabIds = sourceGroup.tabIds.filter((tabId) => tabId !== sourceTabId);
  if (remainingSourceTabIds.length === 0) {
    delete groups[sourceGroup.id];
    tabGroupLayout = removeTabGroupLeaf(tabGroupLayout, sourceGroup.id);
  } else {
    groups[sourceGroup.id] = {
      ...sourceGroup,
      tabIds: remainingSourceTabIds,
      activeTabId:
        sourceGroup.activeTabId === sourceTabId || !remainingSourceTabIds.includes(sourceGroup.activeTabId ?? "")
          ? remainingSourceTabIds[Math.min(sourceIndex, remainingSourceTabIds.length - 1)] ?? remainingSourceTabIds[0]
          : sourceGroup.activeTabId,
    };
  }

  const liveTargetGroup = groups[targetGroup.id];
  if (!liveTargetGroup) return state;
  groups[targetGroup.id] = { ...liveTargetGroup, activeTabId: targetTabId };

  const layoutsByTabId = { ...state.layoutsByTabId };
  delete layoutsByTabId[sourceTabId];
  layoutsByTabId[targetTabId] = {
    ...targetLayout,
    root: nextTargetRoot,
    activeLeafId: moved.activeLeafId ?? findFirstLeafId(moved.root),
    expandedLeafId: null,
    sessionIdsByLeafId: {
      ...targetLayout.sessionIdsByLeafId,
      ...moved.sessionIdsByLeafId,
    },
  };

  return normalizeLayout({
    ...state,
    tabs: state.tabs.filter((tab) => tab.id !== sourceTabId),
    activeTabId: targetTabId,
    focusedGroupId: targetGroup.id,
    tabGroups: groups,
    tabGroupLayout,
    layoutsByTabId,
  });
}

function remapPaneLayout(layout: TabPaneLayout, reservedLeafIds: Set<string>): TabPaneLayout {
  const leafIdMap = new Map<string, string>();
  const visit = (node: PaneNode): PaneNode => {
    if (node.type === "leaf") {
      let nextLeafId = node.leafId;
      while (reservedLeafIds.has(nextLeafId)) nextLeafId = createMovedLeafId();
      reservedLeafIds.add(nextLeafId);
      leafIdMap.set(node.leafId, nextLeafId);
      return nextLeafId === node.leafId ? node : { ...node, leafId: nextLeafId };
    }

    const first = visit(node.first);
    const second = visit(node.second);
    return first === node.first && second === node.second ? node : { ...node, first, second };
  };

  const root = visit(layout.root);
  const sessionIdsByLeafId: Record<string, string> = {};
  for (const [leafId, sessionId] of Object.entries(layout.sessionIdsByLeafId)) {
    sessionIdsByLeafId[leafIdMap.get(leafId) ?? leafId] = sessionId;
  }

  return {
    root,
    activeLeafId: layout.activeLeafId ? (leafIdMap.get(layout.activeLeafId) ?? layout.activeLeafId) : null,
    expandedLeafId: layout.expandedLeafId ? (leafIdMap.get(layout.expandedLeafId) ?? layout.expandedLeafId) : null,
    sessionIdsByLeafId,
  };
}

function findGroupContainingTab(groups: Record<string, TabGroup>, tabId: string): TabGroup | null {
  return Object.values(groups).find((group) => group.tabIds.includes(tabId)) ?? null;
}

function removeTabGroupLeaf(root: TabGroupLayoutNode | null, groupId: string): TabGroupLayoutNode | null {
  if (!root) return null;
  if (root.type === "group") return root.groupId === groupId ? null : root;

  const first = removeTabGroupLeaf(root.first, groupId);
  if (!first) return root.second;
  if (first !== root.first) return { ...root, first };

  const second = removeTabGroupLeaf(root.second, groupId);
  if (!second) return root.first;
  if (second !== root.second) return { ...root, second };
  return root;
}

function createMovedLeafId(): string {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `leaf:moved:${randomPart}`;
}

import { act, cleanup, renderHook } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { BrowserTab, TerminalSession, TerminalTab, Worktree } from "../lib/types";
import { useWorkspaceStore, type WorkspaceServices, type WorkspaceState } from "./workspaceStore";

afterEach(cleanup);

const targetWorktree: Worktree = {
  path: "/repo/target",
  head: "target-head",
  branch: "refs/heads/orca/ws-main/target",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

const sourceWorktree: Worktree = {
  ...targetWorktree,
  path: "/repo/source",
  head: "source-head",
  branch: "refs/heads/orca/ws-main/source",
};

function session(id: string, cwd: string, slug: string): TerminalSession {
  return {
    id,
    cwd,
    worktreePath: cwd,
    workspaceId: "ws-main",
    worktree: { wsId: "ws-main", slug },
    backendSessionId: `backend-${id}`,
    lifecycle: "working",
  };
}

function services(): WorkspaceServices {
  return {
    ensureTerminalEvents: vi.fn(async () => undefined),
    spawnTerminal: vi.fn(async () => "unexpected-backend"),
    getTerminalCwd: vi.fn(async () => null),
    closeTerminal: vi.fn(async () => undefined),
    waitForTerminalExit: vi.fn(async () => undefined),
  };
}

function restoredState(activeTabId = "tab-target"): WorkspaceState {
  const targetTab: TerminalTab = { id: "tab-target", label: "target", sessionId: "session-target" };
  const sourceTab: TerminalTab = { id: "tab-source", label: "source", sessionId: "session-source-primary" };
  return {
    worktrees: [targetWorktree, sourceWorktree],
    activeWorktreePath: targetWorktree.path,
    sessions: {
      "session-target": session("session-target", targetWorktree.path, "target"),
      "session-source-primary": session("session-source-primary", sourceWorktree.path, "source"),
      "session-source-active": session("session-source-active", sourceWorktree.path, "source"),
    },
    layout: {
      tabs: [targetTab, sourceTab],
      activeTabId,
      tabGroups: {
        "group-default": {
          id: "group-default",
          tabIds: [targetTab.id, sourceTab.id],
          activeTabId,
        },
      },
      tabGroupLayout: { type: "group", groupId: "group-default" },
      focusedGroupId: "group-default",
      layoutsByTabId: {
        [targetTab.id]: {
          root: { type: "leaf", leafId: "leaf-target" },
          activeLeafId: "leaf-target",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-target": "session-target" },
        },
        [sourceTab.id]: {
          root: {
            type: "split",
            direction: "vertical",
            first: { type: "leaf", leafId: "leaf-source-primary" },
            second: { type: "leaf", leafId: "leaf-source-active" },
            ratio: 0.5,
          },
          activeLeafId: "leaf-source-active",
          expandedLeafId: null,
          sessionIdsByLeafId: {
            "leaf-source-primary": "session-source-primary",
            "leaf-source-active": "session-source-active",
          },
        },
      },
    },
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

function expectAllSessionsPreserved(state: WorkspaceState) {
  expect(state.sessions["session-target"]).toBeDefined();
  expect(state.sessions["session-source-primary"]).toBeDefined();
  expect(state.sessions["session-source-active"]).toBeDefined();
}

function groupForTab(state: WorkspaceState, tabId: string) {
  return Object.values(state.layout.tabGroups ?? {}).find((group) => group.tabIds.includes(tabId));
}

describe("useWorkspaceStore Orca-style tab ownership moves", () => {
  it("moves a dragged tab into a new split group while preserving its pane tree and PTYs", () => {
    const workspaceServices = services();
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );

    act(() => result.current.restoreWorkspace(restoredState()));
    const targetGroupId = groupForTab(result.current.state, "tab-target")!.id;
    act(() => result.current.moveTabToSplit("tab-source", targetGroupId, "horizontal", "first"));

    expect(new Set(result.current.state.layout.tabs.map((tab) => tab.id))).toEqual(new Set(["tab-target", "tab-source"]));
    expect(result.current.state.layout.activeTabId).toBe("tab-source");
    expect(result.current.state.layout.focusedGroupId).toBe(groupForTab(result.current.state, "tab-source")?.id);

    const targetLayout = result.current.state.layout.layoutsByTabId["tab-target"];
    const sourceLayout = result.current.state.layout.layoutsByTabId["tab-source"];
    expect(targetLayout.root).toEqual({ type: "leaf", leafId: "leaf-target" });
    expect(sourceLayout.root).toEqual({
      type: "split",
      direction: "vertical",
      first: { type: "leaf", leafId: "leaf-source-primary" },
      second: { type: "leaf", leafId: "leaf-source-active" },
      ratio: 0.5,
    });
    expect(sourceLayout.sessionIdsByLeafId).toEqual({
      "leaf-source-primary": "session-source-primary",
      "leaf-source-active": "session-source-active",
    });

    const targetGroup = groupForTab(result.current.state, "tab-target");
    const sourceGroup = groupForTab(result.current.state, "tab-source");
    expect(sourceGroup?.id).not.toBe(targetGroup?.id);
    expect(sourceGroup?.tabIds).toEqual(["tab-source"]);
    expect(result.current.state.layout.tabGroupLayout).toMatchObject({
      type: "split",
      direction: "horizontal",
      first: { type: "group", groupId: sourceGroup?.id },
      second: { type: "group", groupId: targetGroup?.id },
    });

    expectAllSessionsPreserved(result.current.state);
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });

  it("merges a split tab back into a target group at an explicit index without touching its PTYs", () => {
    const workspaceServices = services();
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );
    act(() => result.current.restoreWorkspace(restoredState()));

    const initialGroupId = groupForTab(result.current.state, "tab-target")!.id;
    act(() => result.current.moveTabToSplit("tab-source", initialGroupId, "horizontal", "second"));
    const targetGroupId = groupForTab(result.current.state, "tab-target")!.id;
    act(() => result.current.moveTabToGroup("tab-source", targetGroupId, 0));

    const merged = groupForTab(result.current.state, "tab-source");
    expect(merged?.id).toBe(targetGroupId);
    expect(merged?.tabIds).toEqual(["tab-source", "tab-target"]);
    expect(result.current.state.layout.tabGroupLayout).toEqual({ type: "group", groupId: targetGroupId });
    expect(result.current.state.layout.focusedGroupId).toBe(targetGroupId);
    expect(result.current.state.layout.activeTabId).toBe("tab-source");
    expectAllSessionsPreserved(result.current.state);
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });

  it("moves browser tabs through the same tab-group split and merge reducer path", () => {
    const workspaceServices = services();
    const state = restoredState();
    const browser: BrowserTab = {
      kind: "browser",
      id: "tab-browser",
      label: "Browser",
      browserId: "browser-1",
      url: "http://localhost:3000",
    };
    state.layout.tabs.push(browser);
    state.layout.tabGroups!["group-default"].tabIds.push(browser.id);
    state.layout.layoutsByTabId[browser.id] = {
      root: { type: "leaf", leafId: "leaf-browser" },
      activeLeafId: "leaf-browser",
      expandedLeafId: null,
      sessionIdsByLeafId: { "leaf-browser": "" },
    };
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );
    act(() => result.current.restoreWorkspace(state));

    const targetGroupId = groupForTab(result.current.state, "tab-target")!.id;
    act(() => result.current.moveTabToSplit("tab-browser", targetGroupId, "vertical", "second"));
    expect(groupForTab(result.current.state, "tab-browser")?.id).not.toBe(targetGroupId);

    act(() => result.current.moveTabToGroup("tab-browser", targetGroupId));
    expect(groupForTab(result.current.state, "tab-browser")?.id).toBe(targetGroupId);
    expect(result.current.state.layout.tabs.find((tab) => tab.id === "tab-browser")?.kind).toBe("browser");
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
  });

  it("detaches one terminal pane into a new tab by moving the same local/backend session ownership", () => {
    const workspaceServices = services();
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );
    act(() => result.current.restoreWorkspace(restoredState("tab-source")));

    let detachedTabId: string | null = null;
    act(() => {
      detachedTabId = result.current.detachPaneToTab("tab-source", "leaf-source-active");
    });

    expect(detachedTabId).toBeTruthy();
    const sourceLayout = result.current.state.layout.layoutsByTabId["tab-source"];
    expect(sourceLayout.root).toEqual({ type: "leaf", leafId: "leaf-source-primary" });
    expect(sourceLayout.sessionIdsByLeafId).toEqual({ "leaf-source-primary": "session-source-primary" });

    const detachedLayout = result.current.state.layout.layoutsByTabId[detachedTabId!];
    expect(detachedLayout.root).toEqual({ type: "leaf", leafId: "leaf-source-active" });
    expect(detachedLayout.sessionIdsByLeafId).toEqual({ "leaf-source-active": "session-source-active" });
    const detachedTab = result.current.state.layout.tabs.find((tab) => tab.id === detachedTabId);
    expect(detachedTab?.kind).not.toBe("browser");
    if (detachedTab?.kind !== "browser") expect(detachedTab?.sessionId).toBe("session-source-active");

    expect(result.current.state.sessions["session-source-active"].backendSessionId).toBe("backend-session-source-active");
    expect(Object.keys(result.current.state.sessions)).toHaveLength(3);
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });
});

import { act, cleanup, renderHook } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { TerminalSession, TerminalTab, Worktree } from "../lib/types";
import { useWorkspaceStore, type WorkspaceServices, type WorkspaceState } from "./workspaceStore";

afterEach(cleanup);

const targetWorktree: Worktree = {
  path: "/repo/target",
  head: "target-head",
  branch: "refs/heads/target",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

const sourceWorktree: Worktree = {
  ...targetWorktree,
  path: "/repo/source",
  head: "source-head",
  branch: "refs/heads/source",
};

function terminalSession(id: string, cwd: string): TerminalSession {
  return {
    id,
    cwd,
    worktreePath: cwd,
    workspaceId: "ws-main",
    worktree: { wsId: "ws-main", slug: cwd.endsWith("source") ? "source" : "target" },
    backendSessionId: `backend-${id}`,
    lifecycle: "working",
  };
}

function services(): WorkspaceServices {
  return {
    ensureTerminalEvents: vi.fn(async () => undefined),
    spawnTerminal: vi.fn(async () => "unexpected-backend"),
    getTerminalCwd: vi.fn(async () => null),
    closeTerminal: vi.fn(async () => undefined),
    waitForTerminalExit: vi.fn(async () => undefined),
  };
}

function stateWithSplitSource(): WorkspaceState {
  const targetTab: TerminalTab = { id: "tab-target", label: "target", sessionId: "session-target" };
  const sourceTab: TerminalTab = { id: "tab-source", label: "source", sessionId: "session-source-primary" };
  return {
    worktrees: [targetWorktree, sourceWorktree],
    activeWorktreePath: sourceWorktree.path,
    sessions: {
      "session-target": terminalSession("session-target", targetWorktree.path),
      "session-source-primary": terminalSession("session-source-primary", sourceWorktree.path),
      "session-source-active": terminalSession("session-source-active", sourceWorktree.path),
    },
    layout: {
      tabs: [targetTab, sourceTab],
      activeTabId: "tab-source",
      tabGroups: {
        "group-default": {
          id: "group-default",
          tabIds: [targetTab.id, sourceTab.id],
          activeTabId: sourceTab.id,
        },
      },
      tabGroupLayout: { type: "group", groupId: "group-default" },
      focusedGroupId: "group-default",
      layoutsByTabId: {
        [targetTab.id]: {
          root: { type: "leaf", leafId: "leaf-target" },
          activeLeafId: "leaf-target",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-target": "session-target" },
        },
        [sourceTab.id]: {
          root: {
            type: "split",
            direction: "vertical",
            first: { type: "leaf", leafId: "leaf-source-primary" },
            second: { type: "leaf", leafId: "leaf-source-active" },
            ratio: 0.35,
          },
          activeLeafId: "leaf-source-active",
          expandedLeafId: null,
          sessionIdsByLeafId: {
            "leaf-source-primary": "session-source-primary",
            "leaf-source-active": "session-source-active",
          },
        },
      },
    },
    unreadTabIds: { "tab-source": true },
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

function collectLeafIds(node: WorkspaceState["layout"]["layoutsByTabId"][string]["root"]): string[] {
  if (node.type === "leaf") return [node.leafId];
  return [...collectLeafIds(node.first), ...collectLeafIds(node.second)];
}

describe("useWorkspaceStore pane-targeted tab drop", () => {
  it("moves the existing source pane subtree into the exact target leaf without respawning or closing PTYs", () => {
    const workspaceServices = services();
    const restored = stateWithSplitSource();
    const sourcePrimary = restored.sessions["session-source-primary"];
    const sourceActive = restored.sessions["session-source-active"];
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );

    act(() => result.current.restoreWorkspace(restored));
    act(() =>
      result.current.moveTabToSplit("tab-source", "group-default", "horizontal", "first", {
        tabId: "tab-target",
        leafId: "leaf-target",
      }),
    );

    expect(result.current.state.layout.tabs.map((tab) => tab.id)).toEqual(["tab-target"]);
    expect(result.current.state.layout.layoutsByTabId["tab-source"]).toBeUndefined();
    expect(result.current.state.layout.activeTabId).toBe("tab-target");
    expect(result.current.state.layout.focusedGroupId).toBe("group-default");
    expect(result.current.state.layout.tabGroups?.["group-default"].tabIds).toEqual(["tab-target"]);

    const targetLayout = result.current.state.layout.layoutsByTabId["tab-target"];
    expect(targetLayout.root).toEqual({
      type: "split",
      direction: "horizontal",
      first: {
        type: "split",
        direction: "vertical",
        first: { type: "leaf", leafId: "leaf-source-primary" },
        second: { type: "leaf", leafId: "leaf-source-active" },
        ratio: 0.35,
      },
      second: { type: "leaf", leafId: "leaf-target" },
      ratio: 0.5,
    });
    expect(targetLayout.activeLeafId).toBe("leaf-source-active");
    expect(targetLayout.sessionIdsByLeafId).toEqual({
      "leaf-target": "session-target",
      "leaf-source-primary": "session-source-primary",
      "leaf-source-active": "session-source-active",
    });

    expect(result.current.state.sessions["session-source-primary"]).toBe(sourcePrimary);
    expect(result.current.state.sessions["session-source-active"]).toBe(sourceActive);
    expect(result.current.state.sessions["session-source-active"].cwd).toBe(sourceWorktree.path);
    expect(result.current.state.sessions["session-source-active"].backendSessionId).toBe("backend-session-source-active");
    expect(result.current.state.unreadTabIds["tab-source"]).toBeUndefined();
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });

  it("remaps a colliding legacy leaf id while preserving the local session ownership", () => {
    const workspaceServices = services();
    const restored = stateWithSplitSource();
    restored.layout.layoutsByTabId["tab-target"] = {
      root: { type: "leaf", leafId: "leaf-shared" },
      activeLeafId: "leaf-shared",
      expandedLeafId: null,
      sessionIdsByLeafId: { "leaf-shared": "session-target" },
    };
    restored.layout.layoutsByTabId["tab-source"] = {
      root: { type: "leaf", leafId: "leaf-shared" },
      activeLeafId: "leaf-shared",
      expandedLeafId: null,
      sessionIdsByLeafId: { "leaf-shared": "session-source-primary" },
    };

    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );
    act(() => result.current.restoreWorkspace(restored));
    act(() =>
      result.current.moveTabToSplit("tab-source", "group-default", "vertical", "second", {
        tabId: "tab-target",
        leafId: "leaf-shared",
      }),
    );

    const targetLayout = result.current.state.layout.layoutsByTabId["tab-target"];
    const leafIds = collectLeafIds(targetLayout.root);
    expect(new Set(leafIds).size).toBe(2);
    expect(leafIds).toContain("leaf-shared");
    expect(Object.values(targetLayout.sessionIdsByLeafId)).toEqual(
      expect.arrayContaining(["session-target", "session-source-primary"]),
    );
    expect(targetLayout.sessionIdsByLeafId[targetLayout.activeLeafId!]).toBe("session-source-primary");
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });
});

import { describe, expect, it } from "vitest";

import type { LayoutState, TerminalTab } from "../lib/types";
import { getGroupForTab, layoutReducer, normalizeLayout } from "./layout";
import { moveTabIntoPaneSplit } from "./tabPaneDrop";

function sameTabLayout(): LayoutState {
  const tab: TerminalTab = { id: "tab-main", label: "main", sessionId: "session-a" };
  return normalizeLayout({
    tabs: [tab],
    activeTabId: tab.id,
    layoutsByTabId: {
      [tab.id]: {
        root: {
          type: "split",
          direction: "horizontal",
          first: { type: "leaf", leafId: "leaf-a" },
          second: {
            type: "split",
            direction: "vertical",
            first: { type: "leaf", leafId: "leaf-b" },
            second: { type: "leaf", leafId: "leaf-c" },
            ratio: 0.5,
          },
          ratio: 0.4,
        },
        activeLeafId: "leaf-a",
        expandedLeafId: null,
        sessionIdsByLeafId: {
          "leaf-a": "session-a",
          "leaf-b": "session-b",
          "leaf-c": "session-c",
        },
      },
    },
  });
}

describe("pane-handle edge drop composition", () => {
  it("detaches the existing pane session and reinserts that exact leaf at the target edge", () => {
