    });
    expect(next.layoutsByTabId["tab-main"].activeLeafId).toBe("leaf-a");
    expect(next.layoutsByTabId["tab-main"].sessionIdsByLeafId).toEqual({
      "leaf-a": "session-a",
      "leaf-b": "session-b",
      "leaf-c": "session-c",
    });
  });

  it("preserves pane ownership when a handle is moved to an edge in another tab", () => {
    const source: TerminalTab = { id: "tab-source", label: "source", sessionId: "session-moved" };
    const target: TerminalTab = { id: "tab-target", label: "target", sessionId: "session-target" };
    const state = normalizeLayout({
      tabs: [source, target],
      activeTabId: source.id,
      layoutsByTabId: {
        [source.id]: {
          root: {
            type: "split",
            direction: "horizontal",
            first: { type: "leaf", leafId: "leaf-moved" },
            second: { type: "leaf", leafId: "leaf-remain" },
            ratio: 0.5,
          },
          activeLeafId: "leaf-moved",
          expandedLeafId: null,
          sessionIdsByLeafId: {
            "leaf-moved": "session-moved",
            "leaf-remain": "session-remain",
          },
        },
        [target.id]: {
          root: { type: "leaf", leafId: "leaf-target" },
          activeLeafId: "leaf-target",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-target": "session-target" },
        },
      },
    });
    const targetGroupId = getGroupForTab(state, target.id)!.id;
    const detachedTab: TerminalTab = { id: "tab-detached", label: "source", sessionId: "session-moved" };

    const detached = layoutReducer(state, {
      type: "DETACH_PANE_TO_TAB",
      sourceTabId: source.id,
      leafId: "leaf-moved",
      newTab: detachedTab,
      targetGroupId,
    });
    const next = moveTabIntoPaneSplit(
      detached,
      detachedTab.id,
      target.id,
      "leaf-target",
      "horizontal",
      "second",
    );

    expect(next.tabs.find((tab) => tab.id === source.id)).toMatchObject({ sessionId: "session-remain" });
    expect(next.layoutsByTabId[source.id]).toMatchObject({
      root: { type: "leaf", leafId: "leaf-remain" },
      activeLeafId: "leaf-remain",
      sessionIdsByLeafId: { "leaf-remain": "session-remain" },
    });
    expect(next.layoutsByTabId[target.id].root).toEqual({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "leaf-target" },
      second: { type: "leaf", leafId: "leaf-moved" },
      ratio: 0.5,
    });
    expect(next.layoutsByTabId[target.id].sessionIdsByLeafId).toEqual({
      "leaf-target": "session-target",
      "leaf-moved": "session-moved",
    });
    expect(next.layoutsByTabId[target.id].activeLeafId).toBe("leaf-moved");
  });
});

import { describe, expect, it } from "vitest";

import type { TerminalTab } from "../lib/types";
import { createLayoutState, layoutReducer } from "./layout";

function tab(id: string, sessionId: string): TerminalTab {
  return { id, label: id, sessionId };
}

describe("layoutReducer with per-tab split trees", () => {
  it("initializes each tab with its own independent single-pane root layout", () => {
    const tab1 = tab("tab-1", "session-1");
    const tab2 = tab("tab-2", "session-2");
    const state = createLayoutState([tab1, tab2], tab1.id);

    expect(state.tabs).toHaveLength(2);
    expect(state.activeTabId).toBe("tab-1");
    expect(state.layoutsByTabId["tab-1"].root).toEqual({ type: "leaf", leafId: "leaf-init" });
    expect(state.layoutsByTabId["tab-1"].sessionIdsByLeafId["leaf-init"]).toBe("session-1");
    expect(state.layoutsByTabId["tab-2"].root).toEqual({ type: "leaf", leafId: "leaf-init" });
    expect(state.layoutsByTabId["tab-2"].sessionIdsByLeafId["leaf-init"]).toBe("session-2");
  });

  it("splits any pane in a tab horizontally or vertically without affecting other tabs", () => {
    const tab1 = tab("tab-1", "session-1");
    const tab2 = tab("tab-2", "session-2");
    let state = createLayoutState([tab1, tab2], tab1.id);

    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-right",
      sessionId: "session-1-right",
    });

    expect(state.layoutsByTabId["tab-1"].root).toMatchObject({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "leaf-init" },
      second: { type: "leaf", leafId: "leaf-right" },
      ratio: 0.5,
    });
    expect(state.layoutsByTabId["tab-1"].sessionIdsByLeafId["leaf-right"]).toBe("session-1-right");
    expect(state.layoutsByTabId["tab-1"].activeLeafId).toBe("leaf-right");
    expect(state.layoutsByTabId["tab-2"].root).toEqual({ type: "leaf", leafId: "leaf-init" });

    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-right",
      direction: "vertical",
      newLeafId: "leaf-right-bottom",
      sessionId: "session-1-bottom",
    });

    expect(state.layoutsByTabId["tab-1"].root).toMatchObject({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "leaf-init" },
      second: {
        type: "split",
        direction: "vertical",
        first: { type: "leaf", leafId: "leaf-right" },
        second: { type: "leaf", leafId: "leaf-right-bottom" },
      },
    });
  });

  it("rejects missing split targets and duplicate leaf ids without creating orphan session bindings", () => {
    const initial = createLayoutState([tab("tab-1", "session-1")], "tab-1");

    const missingTarget = layoutReducer(initial, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "missing",
      direction: "horizontal",
      newLeafId: "orphan",
      sessionId: "session-orphan",
    });
    expect(missingTarget).toBe(initial);
    expect(missingTarget.layoutsByTabId["tab-1"].sessionIdsByLeafId).toEqual({ "leaf-init": "session-1" });

    const duplicateLeaf = layoutReducer(initial, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-init",
      sessionId: "session-orphan",
    });
    expect(duplicateLeaf).toBe(initial);
  });

  it("closes an individual pane and collapses the parent split into the sibling", () => {
    const tab1 = tab("tab-1", "session-1");
    let state = createLayoutState([tab1], tab1.id);
    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-2",
      sessionId: "session-2",
    });

    state = layoutReducer(state, { type: "CLOSE_PANE", tabId: "tab-1", leafId: "leaf-2" });

    const tab1Layout = state.layoutsByTabId["tab-1"];
    expect(tab1Layout.root).toEqual({ type: "leaf", leafId: "leaf-init" });
    expect(tab1Layout.activeLeafId).toBe("leaf-init");
    expect(tab1Layout.sessionIdsByLeafId["leaf-2"]).toBeUndefined();
  });

  it("selects the adjacent tab when closing the active tab", () => {
    const tabs = [tab("tab-1", "s1"), tab("tab-2", "s2"), tab("tab-3", "s3"), tab("tab-4", "s4")];
    let state = createLayoutState(tabs, "tab-2");

    state = layoutReducer(state, { type: "CLOSE_TAB", tabId: "tab-2" });
    expect(state.activeTabId).toBe("tab-3");

    state = layoutReducer({ ...state, activeTabId: "tab-4" }, { type: "CLOSE_TAB", tabId: "tab-4" });
    expect(state.activeTabId).toBe("tab-3");
  });

  it("reorders tabs by stable tab id without disturbing active tab or pane layouts", () => {
    const state = createLayoutState([tab("tab-1", "s1"), tab("tab-2", "s2"), tab("tab-3", "s3")], "tab-2");
    const layouts = state.layoutsByTabId;

    const reordered = layoutReducer(state, { type: "REORDER_TAB", tabId: "tab-1", targetIndex: 2 });

    expect(reordered.tabs.map((item) => item.id)).toEqual(["tab-2", "tab-3", "tab-1"]);
    expect(reordered.activeTabId).toBe("tab-2");
    expect(reordered.layoutsByTabId).toBe(layouts);
  });

  it("renames and pins tabs in layout state while rejecting blank titles", () => {
    let state = createLayoutState([tab("tab-1", "s1")], "tab-1");
    state = layoutReducer(state, { type: "RENAME_TAB", tabId: "tab-1", label: "  custom title  " });
    state = layoutReducer(state, { type: "SET_TAB_PINNED", tabId: "tab-1", pinned: true });

    expect(state.tabs[0]).toMatchObject({ label: "custom title", pinned: true });
    const unchanged = layoutReducer(state, { type: "RENAME_TAB", tabId: "tab-1", label: "   " });
    expect(unchanged).toBe(state);
  });

  it("ignores focus requests for leaves that do not exist", () => {
    const state = createLayoutState([tab("tab-1", "session-1")], "tab-1");
    const focused = layoutReducer(state, { type: "FOCUS_PANE", tabId: "tab-1", leafId: "missing" });
    expect(focused).toBe(state);
    expect(focused.layoutsByTabId["tab-1"].activeLeafId).toBe("leaf-init");
  });

  it("normalizes stale pane session mappings to the actual leaf set", () => {
    const state = createLayoutState([tab("tab-1", "session-1")], "tab-1");
    const malformed = {
      ...state,
      layoutsByTabId: {
        ...state.layoutsByTabId,
        "tab-1": {
          ...state.layoutsByTabId["tab-1"],
          sessionIdsByLeafId: { "leaf-init": "session-1", ghost: "session-ghost" },
        },
      },
    };

    const normalized = layoutReducer(malformed, { type: "ACTIVATE_TAB", tabId: "tab-1" });
    expect(normalized.layoutsByTabId["tab-1"].sessionIdsByLeafId).toEqual({ "leaf-init": "session-1" });
  });

  it("swaps pane positions for drag-and-drop reorder", () => {
    let state = createLayoutState([tab("tab-1", "session-1")], "tab-1");
    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-2",
      sessionId: "session-2",
    });

    state = layoutReducer(state, {
      type: "SWAP_PANES",
      tabId: "tab-1",
      sourceLeafId: "leaf-init",
      targetLeafId: "leaf-2",
    });

    expect(state.layoutsByTabId["tab-1"].root).toMatchObject({
      type: "split",
      first: { type: "leaf", leafId: "leaf-2" },
      second: { type: "leaf", leafId: "leaf-init" },
    });
  });

  it("adjusts split ratio at dot path", () => {
    let state = createLayoutState([tab("tab-1", "session-1")], "tab-1");
    state = layoutReducer(state, {
      type: "SPLIT_PANE",
      tabId: "tab-1",
      targetLeafId: "leaf-init",
      direction: "horizontal",
      newLeafId: "leaf-2",
      sessionId: "session-2",
    });

    state = layoutReducer(state, { type: "SET_PANE_RATIO", tabId: "tab-1", path: "", ratio: 0.7 });
    expect(state.layoutsByTabId["tab-1"].root).toMatchObject({ type: "split", ratio: 0.7 });
  });
});

import { describe, expect, it } from "vitest";

import {
  clampRatio,
  collectLeafIds,
  createLeafNode,
  equalizeRatios,
  findFirstLeafId,
  findSiblingLeafId,
  MAX_PANE_RATIO,
  MIN_PANE_RATIO,
  removeLeaf,
  setRatioAtPath,
  splitLeaf,
  swapLeaves,
  type PaneNode,
} from "./paneTree";

function leaf(leafId: string): PaneNode {
  return { type: "leaf", leafId };
}

function split(direction: "horizontal" | "vertical", first: PaneNode, second: PaneNode, ratio = 0.5): PaneNode {
  return { type: "split", direction, first, second, ratio };
}

/** a | (b | c) — a right-nested tree used by several suites. */
function nestedTree(): PaneNode {
  return split("horizontal", leaf("a"), split("vertical", leaf("b"), leaf("c"), 0.4), 0.6);
}

describe("createLeafNode", () => {
  it("uses the provided leaf id", () => {
    expect(createLeafNode("pane-1")).toEqual({ type: "leaf", leafId: "pane-1" });
  });

  it("generates a unique prefixed id when none is provided", () => {
    const first = createLeafNode();
    const second = createLeafNode();

    expect(first.type).toBe("leaf");
    if (first.type !== "leaf" || second.type !== "leaf") throw new Error("expected leaves");
    expect(first.leafId).toMatch(/^pane:/);
    expect(second.leafId).toMatch(/^pane:/);
    expect(first.leafId).not.toBe(second.leafId);
  });
});

describe("clampRatio", () => {
  it("keeps ratios inside the usable range", () => {
    expect(clampRatio(0.5)).toBe(0.5);
    expect(clampRatio(0)).toBe(MIN_PANE_RATIO);
    expect(clampRatio(1)).toBe(MAX_PANE_RATIO);
    expect(clampRatio(-4)).toBe(MIN_PANE_RATIO);
  });

  it("falls back to an even split for non-finite input", () => {
    expect(clampRatio(Number.NaN)).toBe(0.5);
    expect(clampRatio(Number.POSITIVE_INFINITY)).toBe(0.5);
  });
});

describe("splitLeaf", () => {
  it("splits a root leaf with the new pane in the second position by default", () => {
    expect(splitLeaf(leaf("a"), "a", "b", "horizontal")).toEqual(
      split("horizontal", leaf("a"), leaf("b"), 0.5),
    );
  });

  it("places the new pane first when requested", () => {
    expect(splitLeaf(leaf("a"), "a", "b", "vertical", "first")).toEqual(
      split("vertical", leaf("b"), leaf("a"), 0.5),
    );
  });

  it("honours an explicit ratio and clamps out-of-range values", () => {
    const tree = splitLeaf(leaf("a"), "a", "b", "horizontal", "second", 0.25);
    expect(tree).toMatchObject({ ratio: 0.25 });
    expect(splitLeaf(leaf("a"), "a", "b", "horizontal", "second", 5)).toMatchObject({
      ratio: MAX_PANE_RATIO,
    });
  });

  it("splits a nested leaf while preserving the surrounding structure", () => {
    const next = splitLeaf(nestedTree(), "c", "d", "horizontal");

    expect(next).toEqual(
      split(
        "horizontal",
        leaf("a"),
        split("vertical", leaf("b"), split("horizontal", leaf("c"), leaf("d"), 0.5), 0.4),
        0.6,
      ),
    );
  });

  it("returns the original tree when the target leaf is missing", () => {
    const tree = nestedTree();
    expect(splitLeaf(tree, "missing", "d", "horizontal")).toBe(tree);
  });

  it("does not mutate the input tree", () => {
    const tree = nestedTree();
    const snapshot = structuredClone(tree);
    splitLeaf(tree, "b", "d", "vertical");
    expect(tree).toEqual(snapshot);
  });

  it("shares untouched subtrees with the previous tree", () => {
    const tree = nestedTree();
    const next = splitLeaf(tree, "c", "d", "horizontal");

    if (tree.type !== "split" || next.type !== "split") throw new Error("expected splits");
    expect(next.first).toBe(tree.first);
    expect(next).not.toBe(tree);
  });
});

describe("removeLeaf", () => {
  it("returns null when removing the only leaf", () => {
    expect(removeLeaf(leaf("a"), "a")).toBeNull();
  });

  it("collapses the parent split into the surviving sibling", () => {
    const tree = split("horizontal", leaf("a"), leaf("b"));
    expect(removeLeaf(tree, "a")).toEqual(leaf("b"));
    expect(removeLeaf(tree, "b")).toEqual(leaf("a"));
  });

  it("collapses into a sibling subtree rather than a single leaf", () => {
    const next = removeLeaf(nestedTree(), "a");
    expect(next).toEqual(split("vertical", leaf("b"), leaf("c"), 0.4));
  });

  it("removes a deeply nested leaf and keeps the outer split", () => {
    expect(removeLeaf(nestedTree(), "c")).toEqual(split("horizontal", leaf("a"), leaf("b"), 0.6));
  });

  it("returns the original tree when the leaf is missing", () => {
    const tree = nestedTree();
    expect(removeLeaf(tree, "missing")).toBe(tree);
  });

  it("supports removing every leaf one at a time down to null", () => {
    let tree: PaneNode | null = nestedTree();
    for (const id of ["b", "a", "c"]) {
      tree = removeLeaf(tree as PaneNode, id);
    }
    expect(tree).toBeNull();
  });

  it("does not mutate the input tree", () => {
    const tree = nestedTree();
    const snapshot = structuredClone(tree);
    removeLeaf(tree, "b");
    expect(tree).toEqual(snapshot);
  });
});

describe("setRatioAtPath", () => {
  it("sets the ratio at the root for an empty path", () => {
    expect(setRatioAtPath(nestedTree(), "", 0.3)).toMatchObject({ ratio: 0.3 });
  });

  it("sets the ratio on a nested split addressed by dot notation", () => {
    const next = setRatioAtPath(nestedTree(), "second", 0.8);
    expect(next).toEqual(
      split("horizontal", leaf("a"), split("vertical", leaf("b"), leaf("c"), 0.8), 0.6),
    );
  });

  it("resolves multi-segment paths", () => {
    const tree = split("horizontal", leaf("a"), split("vertical", leaf("b"), split("horizontal", leaf("c"), leaf("d"))));
    const next = setRatioAtPath(tree, "second.second", 0.7);

    if (next.type !== "split" || next.second.type !== "split" || next.second.second.type !== "split") {
      throw new Error("expected nested splits");
    }
    expect(next.second.second.ratio).toBe(0.7);
    expect(next.second.ratio).toBe(0.5);
    expect(next.ratio).toBe(0.5);
  });

  it("clamps the ratio into the usable range", () => {
    expect(setRatioAtPath(nestedTree(), "", 0.99)).toMatchObject({ ratio: MAX_PANE_RATIO });
    expect(setRatioAtPath(nestedTree(), "", -1)).toMatchObject({ ratio: MIN_PANE_RATIO });
  });

  it("returns the original tree for paths that do not resolve to a split", () => {
    const tree = nestedTree();
    expect(setRatioAtPath(tree, "first", 0.3)).toBe(tree);
    expect(setRatioAtPath(tree, "second.first.second", 0.3)).toBe(tree);
    expect(setRatioAtPath(tree, "third", 0.3)).toBe(tree);
    expect(setRatioAtPath(leaf("a"), "first", 0.3)).toEqual(leaf("a"));
  });

  it("returns the original tree when the ratio is unchanged", () => {
    const tree = nestedTree();
    expect(setRatioAtPath(tree, "", 0.6)).toBe(tree);
  });

  it("does not mutate the input tree", () => {
    const tree = nestedTree();
    const snapshot = structuredClone(tree);
    setRatioAtPath(tree, "second", 0.25);
    expect(tree).toEqual(snapshot);
  });
});

describe("findFirstLeafId", () => {
  it("returns the id of a root leaf", () => {
    expect(findFirstLeafId(leaf("a"))).toBe("a");
  });

  it("descends into the first branch of nested splits", () => {
    expect(findFirstLeafId(nestedTree())).toBe("a");
    expect(findFirstLeafId(split("vertical", nestedTree(), leaf("z")))).toBe("a");
  });
});

describe("collectLeafIds", () => {
  it("returns a single id for a leaf tree", () => {
    expect(collectLeafIds(leaf("a"))).toEqual(["a"]);
  });

  it("returns ids in first-to-second document order", () => {
    expect(collectLeafIds(nestedTree())).toEqual(["a", "b", "c"]);
  });

  it("tracks ids across repeated splits", () => {
    let tree: PaneNode = createLeafNode("a");
    tree = splitLeaf(tree, "a", "b", "horizontal");
    tree = splitLeaf(tree, "b", "c", "vertical");
    tree = splitLeaf(tree, "a", "d", "vertical", "first");

    expect(collectLeafIds(tree)).toEqual(["d", "a", "b", "c"]);
  });
});

describe("findSiblingLeafId", () => {
  it("returns null for a single-leaf tree", () => {
    expect(findSiblingLeafId(leaf("a"), "a")).toBeNull();
  });

  it("returns the neighbouring leaf in a simple split", () => {
    const tree = split("horizontal", leaf("a"), leaf("b"));
    expect(findSiblingLeafId(tree, "a")).toBe("b");
    expect(findSiblingLeafId(tree, "b")).toBe("a");
  });

  it("returns the closest sibling inside a nested split", () => {
    const tree = nestedTree();
    expect(findSiblingLeafId(tree, "b")).toBe("c");
    expect(findSiblingLeafId(tree, "c")).toBe("b");
  });

  it("returns the first leaf of a sibling subtree when the sibling is a split", () => {
    expect(findSiblingLeafId(nestedTree(), "a")).toBe("b");
  });

  it("returns null when the leaf is missing", () => {
    expect(findSiblingLeafId(nestedTree(), "missing")).toBeNull();
  });
});

describe("swapLeaves", () => {
  it("swaps two sibling leaves", () => {
    const tree = split("horizontal", leaf("a"), leaf("b"), 0.3);
    expect(swapLeaves(tree, "a", "b")).toEqual(split("horizontal", leaf("b"), leaf("a"), 0.3));
  });

  it("swaps leaves across different depths without changing structure or ratios", () => {
    const next = swapLeaves(nestedTree(), "a", "c");

    expect(next).toEqual(
      split("horizontal", leaf("c"), split("vertical", leaf("b"), leaf("a"), 0.4), 0.6),
    );
    expect(collectLeafIds(next)).toEqual(["c", "b", "a"]);
  });

  it("is symmetric in its arguments", () => {
    expect(swapLeaves(nestedTree(), "a", "c")).toEqual(swapLeaves(nestedTree(), "c", "a"));
  });

  it("restores the original tree when applied twice", () => {
    const tree = nestedTree();
    expect(swapLeaves(swapLeaves(tree, "a", "c"), "a", "c")).toEqual(tree);
  });

  it("returns the original tree when both ids are the same", () => {
    const tree = nestedTree();
    expect(swapLeaves(tree, "a", "a")).toBe(tree);
  });

  it("returns the original tree when either leaf is missing", () => {
    const tree = nestedTree();
    expect(swapLeaves(tree, "a", "missing")).toBe(tree);
